'use strict';
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>Array.from(r.querySelectorAll(s));
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const time=v=>v?new Date(v).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}):'—';
const number=v=>Number(v||0).toLocaleString('zh-CN');
const roleNames={admin:'管理员',operator:'运营',editor:'内容编辑',viewer:'只读成员'};
const statusNames={published:'已发布',draft:'草稿',archived:'已归档',submitted:'待复核',pending:'待跟进',processing:'处理中',resolved:'处理完成',active:'可登录',inactive:'已停用'};
const kindNames={consultation:'商品咨询',claim:'售后反馈',tour:'出行意向'};
const routeNames={home:'首页',evidence:'事实中心',consumer:'选一箱桃',trace:'批次溯源',ip:'小桃满IP',operator:'协作运营',content:'内容工作室',rural:'农文旅',service:'收货售后',competition:'赛事讲解',records:'访客记录',api:'接口说明'};
const calendarDate=(offset=0)=>new Date(Date.now()+8*3600000+offset*86400000).toISOString().slice(0,10);
const state={user:null,csrf:'',modules:{},route:'overview',items:[],page:1,q:'',analyticsTab:'summary',mediaTab:'uploaded',recordKind:'',recordStatus:'',recordSearch:'',recordPage:1,auditPage:1,start:calendarDate(-6),end:calendarDate(),eventPage:1};
let generation=0,editing=null,noticeTimer;
const canEdit=()=>['admin','operator','editor'].includes(state.user?.role),canPublish=()=>['admin','operator'].includes(state.user?.role),isAdmin=()=>state.user?.role==='admin';
const pill=s=>`<span class="pill ${esc(s)}">${esc(statusNames[s]||s)}</span>`;
const button=(text,action,value='',cls='small')=>`<button type="button" class="${cls}" data-action="${action}" data-value="${esc(value)}">${text}</button>`;
const heading=(title,copy,actions='')=>`<div class="page-heading"><div><p class="eyebrow">数商桃乡 / 管理工作台</p><h1>${esc(title)}</h1><p>${esc(copy)}</p></div><div class="heading-actions">${actions}</div></div>`;
const empty=(title='还没有记录',copy='新的内容或操作会显示在这里。')=>`<div class="empty"><img src="/assets/web/xiaotaoman.webp" alt=""><b>${esc(title)}</b><p>${esc(copy)}</p></div>`;
function notice(message){$('#notice').textContent=message;$('#notice').classList.add('show');clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>$('#notice').classList.remove('show'),4000);}
function showError(error,form){const target=form?.isConnected?$('.form-error',form):null;if(target){target.textContent=error.message;target.hidden=false;}else notice(error.message||'操作未完成，请重试');}
async function busy(element,fn){if(element?.dataset.busy)return;const text=element?.innerHTML;if(element){element.dataset.busy='1';element.disabled=true;element.textContent='处理中…';}try{return await fn();}finally{if(element?.isConnected){delete element.dataset.busy;element.disabled=false;element.innerHTML=text;if(element.dataset.copyPending){delete element.dataset.copyPending;window.PeachUI?.copied(element);}}}}
async function api(path,{method='GET',body,raw=false,timeout=20000}={}){const headers={'X-Peach-Request':'1'};if(state.csrf)headers['X-CSRF-Token']=state.csrf;if(body&&!(body instanceof FormData))headers['Content-Type']='application/json';const response=await fetch((location.pathname.startsWith('/demo/')?'/demo/api':'/api')+path,{method,headers,credentials:'same-origin',signal:AbortSignal.timeout(timeout),body:body instanceof FormData?body:body?JSON.stringify(body):undefined});if(raw&&response.ok)return response;const json=await response.json().catch(()=>({error:{message:'服务返回异常，请确认已运行后台服务'}}));if(!response.ok){const e=Error(json.error?.message||'请求失败');e.status=response.status;if(response.status===401&&!path.endsWith('/login'))showLogin();throw e;}return json.data;}
function showLogin(){state.user=null;state.csrf='';$('#workspace').hidden=true;$('#login-screen').hidden=false;if($('#editor').open)$('#editor').close();}
function modal(title,body){$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=body;if(!$('#editor').open)$('#editor').showModal();}
function closeModal(){if(state.user?.mustChangePassword)return notice('首次登录请先修改临时密码');$('#editor').close();editing=null;}
function nav(){const data=['admin','operator','viewer'].includes(state.user.role);const group=(label,items)=>`<div class="nav-group"><span>${label}</span>${items.map(([id,name,icon='·'])=>`<a class="nav-item ${state.route===id?'active':''}" href="#${id}"><i>${icon}</i>${name}</a>`).join('')}</div>`;const folds=(label,items)=>`<details class="nav-fold" ${items.some(([id])=>state.route===id)?'open':''}><summary>${label}</summary>${group('',items)}</details>`;$('#navigation').innerHTML=group('工作台',[['overview','工作总览','⌂'],['project','项目与流程','◎'],...(data?[['work/summary','经营看板','↗'],['analytics','网站访问','◷'],['records','咨询与售后','↺']]:[]),['work/tasks','协作与验收','✓'],...(isAdmin()?[['work/collaborators','协作人员档案','人']]:[])])+group('智能辅助',[...(canEdit()?[['materials','资料导入与归档','⇧'],['ai-copy','商品描述生成','✦']]:[]),...(data?[['ai-dashboard','智能数据看板','↗']]:[]),...(isAdmin()?[['cms/ai_settings','规则与开关','⚙']]:[])])+folds('商品与批次',[['cms/products','商品规格'],['cms/scenarios','消费场景'],['cms/batches','批次事实'],['cms/trace_steps','事实链步骤']])+folds('小桃满与内容',[['cms/ip_profile','角色与规范'],['cms/ip_series','IP栏目与内容'],['cms/templates','渠道模板'],['drafts','草稿与审核'],['media','素材库']])+(data?folds('成交、客户与复盘',[['work/orders','订单与履约'],['work/customers','客户与回访'],['work/signals','市场与问题'],['work/decisions','建议与执行'],['work/experiments','小范围验证']]):'')+folds('研究证据',[['cms/source_library','项目资料档案'],['cms/research_sets','调查分组与口径'],['cms/survey_rows','问卷完整选项'],['cms/interviews','访谈与依据']])+folds('页面与服务',[['cms/navigation','首页入口与导航'],['cms/home_groups','首页分组'],['cms/interface_text','按钮、提示与表单'],['cms/feature_controls','功能开放与说明'],['cms/pages','页面文案'],['cms/faqs','收货与售后FAQ'],['cms/tours','农文旅路线'],['cms/social','联系入口'],['cms/slides','赛事讲解']])+group('系统管理',[...(data?[['audit','操作记录']]:[]),...(isAdmin()?[['users',state.user.singleAccount?'唯一管理员':'成员与权限'],['cms/settings','网站设置'],['system','备份与运行']]:[])]);$('#current-user').textContent=state.user.name+' · '+roleNames[state.user.role];}
async function start(){if(state.user.demo&&!document.querySelector('.demo-scope-banner')){const banner=document.createElement('aside');banner.className='demo-scope-banner';banner.textContent='模拟演示区 · 所有订单、客户、库存与效果均为模拟数据，修改不会影响正式平台。';$('#workspace').prepend(banner);}document.querySelector('[data-action="password"]').hidden=!!state.user.demo;state.modules=(await api('/admin/schema')).modules;$('#login-screen').hidden=true;$('#workspace').hidden=false;nav();await load();}
function dates(){return `<label>开始日期<input type="date" name="start" value="${state.start}" required></label><label>结束日期<input type="date" name="end" value="${state.end}" required></label>`;}
const rangeQuery=()=>new URLSearchParams({start:state.start,end:state.end}).toString();
function stat(label,value,note){return `<div class="stat panel"><span>${esc(label)}</span><b>${esc(value)}</b><small>${esc(note)}</small></div>`;}
function chart(daily){if(!daily.length)return empty('还没有访问记录','从访客打开已接入的网站后开始累计。');const w=650,h=175,pad=22,max=Math.max(1,...daily.map(d=>Number(d.pv)));const points=daily.map((d,i)=>[pad+i*(w-pad*2)/Math.max(1,daily.length-1),h-pad-Number(d.pv)/max*(h-pad*2)]);return `<svg class="chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="页面浏览量趋势">${[0,.5,1].map(v=>`<line x1="${pad}" y1="${pad+v*(h-pad*2)}" x2="${w-pad}" y2="${pad+v*(h-pad*2)}"></line><text x="1" y="${pad+v*(h-pad*2)}">${Math.round(max*(1-v))}</text>`).join('')}<polyline points="${points.map(x=>x.join(',')).join(' ')}"></polyline>${points.map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="4"><title>${esc(daily[i].date)}：${daily[i].pv}次浏览 / ${daily[i].uv}位访客</title></circle>`).join('')}<text x="${pad}" y="${h-1}">${esc(daily[0].date)}</text><text x="${w-pad}" y="${h-1}" text-anchor="end">${esc(daily.at(-1).date)}</text></svg>`;}
function table(headers,rows){return rows.length?`<div class="table-scroll"><table class="data-table"><thead><tr>${headers.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>'<tr>'+row.map(x=>`<td>${x}</td>`).join('')+'</tr>').join('')}</tbody></table></div>`:empty();}
function paginate(total,page,limit,action){return `<div class="pagination"><span>共 ${number(total)} 条 · 第 ${page} / ${Math.max(1,Math.ceil(total/limit))} 页</span><div><button class="small" type="button" data-action="${action}" data-value="${page-1}" ${page<=1?'disabled':''}>上一页</button><button class="small" type="button" data-action="${action}" data-value="${page+1}" ${page*limit>=total?'disabled':''}>下一页</button></div></div>`;}
async function overview(){if(state.user.role==='editor')return heading('今天，整理好一份内容。','你可以维护网站资料、上传素材和提交内容审核。')+`<div class="quick-list">${['products','ip_series','survey_rows','pages'].map(m=>`<a href="#cms/${m}">${state.modules[m].label}<span>↗</span></a>`).join('')}<a href="#drafts">内容草稿与审核 <span>↗</span></a></div>`;const [data,records]=await Promise.all([api('/admin/analytics/summary?'+rangeQuery()),api('/admin/records?status=pending&limit=5')]);return heading('每一条信息，都有下文。','这里是网站真实记录的总览。访问数字从接入后开始累计，不使用示例数据充数。',button('刷新数据','reload','','primary'))+`<div class="callout"><img src="/assets/web/xiaotaoman.webp" alt=""><div><h3>先把事实补全，再让小桃满讲清楚。</h3><p>改价格、批次和活动安排，请保存后检查，再点“发布”。咨询和反馈在“咨询与售后”统一处理。</p></div></div><div class="stats">${stat('近7天页面浏览',number(data.total.pv),'PV · 访客页面浏览次数')}${stat('近7天独立访客',number(data.total.uv),'UV · 匿名浏览器估算')}${stat('待跟进业务',number(records.total),'商品咨询 / 售后 / 出行意向')}${stat('当前活跃访客',number(data.activeVisitors),'近5分钟产生访问记录')}</div><div class="two-columns"><section class="panel"><div class="panel-top"><h2>访问趋势</h2><a href="#analytics">查看完整数据 ↗</a></div>${chart(data.daily)}</section><section class="panel"><div class="panel-top"><h2>常用工作</h2><small>资料 → 发布 → 跟进</small></div><div class="quick-list"><a href="#cms/products">更新商品与规格 <span>↗</span></a><a href="#cms/batches">补齐批次事实 <span>↗</span></a><a href="#cms/ip_series">维护小桃满栏目 <span>↗</span></a><a href="#records">处理咨询和反馈 <span>↗</span></a></div></section></div><section class="panel" style="margin-top:22px"><div class="panel-top"><h2>等待你跟进</h2><a href="#records">全部记录 ↗</a></div>${table(['业务','称呼与地区','时间','操作'],records.items.map(r=>[esc(kindNames[r.kind]),`${esc(r.name)}<small>${esc(r.region)}</small>`,time(r.createdAt),button('查看','record',r.id)]))}</section>`;}
async function analytics(){const tabs=[['summary','概览'],['events','访问明细'],['requests','HTTP请求与错误']];let body='';if(state.analyticsTab==='summary'){const d=await api('/admin/analytics/summary?'+rangeQuery());body=`<div class="stats">${stat('页面浏览 PV',number(d.total.pv),'所选日期内页面访问')}${stat('独立访客 UV',number(d.total.uv),'按匿名浏览器标识估算')}${stat('访问会话',number(d.total.sessions),'30分钟无操作后新会话')}${stat('成功提交意向',number(d.total.conversions),'服务端保存成功，非成交订单')}</div><div class="two-columns"><section class="panel"><div class="panel-top"><h2>每天的访问</h2><small>北京时间</small></div>${chart(d.daily)}${table(['日期','PV','UV','意向提交'],d.daily.map(x=>[esc(x.date),number(x.pv),number(x.uv),number(x.conversions)]))}</section><section class="panel"><h2>访问质量</h2><div class="settings-values"><div><small>按钮点击</small><b>${number(d.total.clicks)}次</b></div><div><small>单页会话占比</small><b>${d.bounceRate}%</b></div><div><small>可见停留合计</small><b>${number(Math.round(Number(d.total.duration)/60))}分钟</b></div><div><small>HTTP错误 / 请求总数</small><b>${number(d.requests.errors)} / ${number(d.requests.total)}</b></div></div><p class="wide-note">最早记录：${time(d.firstEventAt)}<br>${esc(d.notes)}</p></section><section class="panel"><h2>页面表现</h2>${table(['页面','PV','UV','停留秒数'],d.pages.map(x=>[esc(routeNames[x.route]||x.route),number(x.pv),number(x.uv),number(x.duration)]))}</section><section class="panel"><h2>来源与设备</h2>${table(['来源域名','PV','UV'],d.sources.map(x=>[esc(x.referrer),number(x.pv),number(x.uv)]))}${table(['设备 / 浏览器 / 系统','PV'],d.devices.map(x=>[esc([x.device,x.browser,x.os].join(' / ')),number(x.pv)]))}</section><section class="panel"><h2>常用按钮</h2>${table(['页面','动作','次数'],d.clicks.map(x=>[esc(routeNames[x.route]||x.route),esc(x.target),number(x.n)]))}</section><section class="panel"><h2>提交转化</h2>${table(['成功提交类型','数量'],d.conversions.map(x=>[esc(kindNames[x.target]||x.target),number(x.n)]))}<p class="wide-note">拒绝统计、DNT或已知机器人流量不计入匿名访问。HTTP请求与访客浏览是不同口径。</p></section></div>`;}else if(state.analyticsTab==='events'){const d=await api('/admin/analytics/events?'+rangeQuery()+'&page='+state.eventPage);body=`<section class="panel">${table(['时间','事件 / 页面','访客 / 会话','目标 / 来源','设备','停留'],d.items.map(x=>[time(x.created_at),`${esc({pageview:'浏览',click:'点击',engagement:'停留',conversion:'提交'}[x.event])}<small>${esc(routeNames[x.route]||x.route)}</small>`,`${esc(x.visitor)}<small>${esc(x.session_id.slice(0,12))}</small>`,`${esc(x.target||'—')}<small>${esc(x.referrer)}</small>`,`${esc(x.device)}<small>${esc(x.browser+' / '+x.os)}</small>`,x.duration+'秒']))}${paginate(d.total,d.page,d.limit,'event-page')}</section>`;}else{const d=await api('/admin/requests?'+rangeQuery()+'&page='+state.eventPage);body=`<section class="panel"><p class="muted">包含前台、后台、接口、图片等HTTP请求；不保存请求体、密码、Cookie或完整IP。</p>${table(['时间','请求','状态','耗时','请求编号'],d.items.map(x=>[time(x.created_at),`<b>${esc(x.method)}</b> <code>${esc(x.path)}</code>`,pill(String(x.status)),x.duration+'ms',`<small>${esc(x.id)}</small>`]))}${paginate(d.total,d.page,d.limit,'event-page')}</section>`;}return heading('看清访问从哪里来。','所有数字均来自接入后的记录。日期筛选统一按北京时间统计。',button('导出访问CSV','analytics-export','','primary'))+`<form class="toolbar" data-form="dates">${dates()}<button type="submit">查询</button></form><div class="subtabs">${tabs.map(([k,t])=>button(t,'analytics-tab',k,k===state.analyticsTab?'active':'')).join('')}</div>`+body;}
async function cms(module){const d=state.modules[module];if(!d)throw Error('该模块不存在');const ticket=generation,items=await api('/admin/content?module='+encodeURIComponent(module));if(['scenarios','batches'].includes(module))state.productOptions=await api('/catalog');if(ticket===generation)state.items=items;return heading(d.label,d.help,canEdit()&&!d.singleton&&!['pages','research_sets','navigation','home_groups','interface_text'].includes(module)?button('＋ 新增内容','content-new',module,'primary'):'')+`<p class="module-project-note"><a href="#project">查看本模块对应的项目流程与下一步 ↗</a></p><section class="panel"><div class="toolbar"><label class="search">搜索编号、名称或内容<input id="cms-search" type="search" value="${esc(state.q)}" placeholder="输入关键词"></label><label>状态<select id="cms-status"><option value="">全部</option><option value="published">已发布</option><option value="draft">草稿 / 已改未发布</option><option value="archived">已归档</option></select></label><span class="muted">${module==='source_library'?'资料仅在后台查阅，不随前台接口公开。可搜索原文件名、正文、类别及来源。':'保存草稿不会改动已发布版本。'}</span></div><div id="cms-list"></div></section>`;}
function contentList(){const module=state.route.split('/')[1],filter=$('#cms-status')?.value||'',rows=state.items.filter(x=>(!state.q||JSON.stringify([x.slug,x.data]).toLowerCase().includes(state.q.toLowerCase()))&&(!filter||(filter==='draft'?x.status==='draft'||JSON.stringify(x.data)!==JSON.stringify(x.published):x.status===filter))),page=state.page,limit=15;$('#cms-list').innerHTML=table(['编号与名称','状态','更新时间','排序','操作'],rows.slice((page-1)*limit,page*limit).map(x=>[`${esc(x.title)}<small>${esc(x.slug)}${module==='survey_rows'?' · '+esc(x.data.label):module==='source_library'?' · '+esc(state.modules.source_library.fields.find(f=>f.key==='category').options[x.data.category]):''}</small>`,pill(x.status)+(x.published&&JSON.stringify(x.data)!==JSON.stringify(x.published)?'<small>有修改尚未发布</small>':''),time(x.updatedAt),x.sortOrder,`<div class="actions">${button(canEdit()?'编辑':'查看','content-edit',x.id)}${button('版本','content-history',x.id)}</div>`]))+paginate(rows.length,page,limit,'content-page');}
function blankData(def){return Object.fromEntries(def.fields.map(f=>[f.key,['pairs','lines','metrics','proofs'].includes(f.type)?[]:f.type==='checkbox'?f.default===true:f.type==='number'?null:f.type==='select'?Object.keys(f.options)[0]:'']));}
function repeatRow(type,value){const values=type==='metrics'?[value[0],Array.isArray(value[1])?value[1].join(','):value[1],value[2]??'',value[3]]:value;const placeholders=type==='metrics'?['题号','A,B 或 人数','有效分母','指标名称']:type==='proofs'?['数字','标题','说明']:['字段名称','字段内容'];return `<div class="list-row ${type==='metrics'?'metric':type==='proofs'?'proof':''}">${placeholders.map((p,i)=>`<input aria-label="${p}" placeholder="${p}" value="${esc(values[i]??'')}" maxlength="3000">`).join('')}${button('×','remove-row','','icon')}</div>`;}
function fieldHtml(f,value){const required=f.required?'required':'';if(f.key==='productId'&&state.productOptions)return `<label>${esc(f.label)}<select name="${f.key}" ${required}><option value="">请选择规格</option>${state.productOptions.map(x=>`<option value="${esc(x.id)}" ${x.id===value?'selected':''}>${esc(x.name)} · ${esc(x.id)}</option>`).join('')}</select></label>`;if(['pairs','metrics','proofs'].includes(f.type))return `<div class="list-field full" data-field="${f.key}" data-type="${f.type}"><span class="field-label">${esc(f.label)}</span><div class="list-rows">${(value||[]).map(row=>repeatRow(f.type,row)).join('')}</div>${button('＋ 添加一行','add-row',f.key)}<small class="field-help">${esc(f.help||(f.type==='metrics'?'题号 | 选项编码（逗号分隔）或引用人数 | 引用分母 | 指标名称':'可逐项录入，无需编辑代码。'))}</small></div>`;if(f.type==='checkbox')return `<label class="full check-row"><input name="${f.key}" type="checkbox" ${(value===undefined?f.default===true:value)?'checked':''}>${esc(f.label)}</label>`;if(f.type==='select')return `<label>${esc(f.label)}<select name="${f.key}" ${required}>${Object.entries(f.options).map(([v,t])=>`<option value="${esc(v)}" ${value===v?'selected':''}>${esc(t)}</option>`).join('')}</select></label>`;if(f.type==='textarea'||f.type==='lines')return `<label class="full">${esc(f.label)}<textarea name="${f.key}" ${f.readonly?'readonly':''} rows="${f.type==='lines'?3:4}" ${required}>${esc(f.type==='lines'?(value||[]).join('\n'):value)}</textarea>${f.help?`<small>${esc(f.help)}</small>`:''}</label>`;if(f.type==='image')return `<label class="full">${esc(f.label)}<div class="image-input"><input name="${f.key}" value="${esc(value)}" placeholder="从素材库选择图片"><button type="button" data-action="pick-image" data-value="${f.key}">选图</button></div>${value?`<img class="media-preview" src="/${esc(value).replace(/^\//,'')}" alt="所选配图">`:''}</label>`;return `<label>${esc(f.label)}${f.required?' *':''}<input name="${f.key}" type="${f.type==='date'?'date':f.type==='number'?'number':'text'}" value="${esc(value)}" ${required} ${f.type==='number'?`min="${f.min??0}" max="${f.max??10000000}" step="${f.key==='shippingFee'?'0.01':'1'}"`:''}>${f.nullable?'<small>未知请留空；0表示已确认数值为0。</small>':''}</label>`;}
function contentEditor(module,item){editing={module,item};const def=state.modules[module],data=item?.data||blankData(def);modal((item?'编辑':'新增')+' · '+def.label,`<p class="notice-box">${esc(def.help)}</p><form data-form="content"><div class="form-grid"><label>内容编号 *<input name="slug" pattern="[a-zA-Z0-9][a-zA-Z0-9_-]{0,79}" value="${esc(item?.slug||(def.singleton?(def.fixedSlug||'site'):''))}" required ${item?'readonly':''}><small>${module==='source_library'?'档案仅在后台查阅；已有编号固定。':'发布后用于识别此内容；已有编号固定。'}</small></label><label>排序（数字越小越靠前）<input name="sortOrder" type="number" min="0" max="100000" value="${item?.sortOrder??state.items.length}" required></label>${def.fields.map(f=>fieldHtml(f,data[f.key])).join('')}</div><p class="form-error" role="alert" hidden></p><div class="dialog-actions"><div>${canEdit()?'<button type="submit" class="primary">保存草稿</button>':''}${item&&canPublish()?button(module==='source_library'?'保存档案版本（仅后台）':'发布到前台','content-publish',item.id):''}${item&&module!=='source_library'?button('预览页面','content-preview',item.id):''}</div><div>${item&&canPublish()&&!['pages','settings','research_sets','ip_profile','feature_controls','navigation','home_groups'].includes(module)?button('撤下','content-unpublish',item.id,'small danger')+button('归档','content-archive',item.id,'small danger'):''}${button('关闭','close')}</div></div></form>`);if(!canEdit())$$('input,textarea,select',$('#dialog-body')).forEach(x=>x.disabled=true);}
function readContent(form){const def=state.modules[editing.module],data={};for(const f of def.fields){if(['pairs','metrics','proofs'].includes(f.type)){data[f.key]=$$(`[data-field="${f.key}"] .list-row`,form).map(row=>{const values=$$('input',row).map(x=>x.value.trim());return f.type==='metrics'?[values[0],/^\d+$/.test(values[1])?Number(values[1]):values[1].split(/[,，]/).map(x=>x.trim()).filter(Boolean),values[2]?Number(values[2]):null,values[3]]:values;});}else if(f.type==='checkbox')data[f.key]=form.elements[f.key].checked;else if(f.type==='number')data[f.key]=form.elements[f.key].value===''?null:Number(form.elements[f.key].value);else if(f.type==='lines')data[f.key]=form.elements[f.key].value.split('\n').map(x=>x.trim()).filter(Boolean);else data[f.key]=form.elements[f.key].value;}return data;}
async function saveContent(){const form=$('[data-form="content"]');if(!form.reportValidity())throw Error('请补齐必填字段');const{module,item}=editing,body={module,slug:form.elements.slug.value,data:readContent(form),sortOrder:Number(form.elements.sortOrder.value),...(item?{version:item.version}:{})};const saved=await api('/admin/content'+(item?'/'+item.id:''),{method:item?'PATCH':'POST',body});contentEditor(module,saved);notice('草稿已保存；确认内容后再发布。');return saved;}
async function contentHistory(id){const item=state.items.find(x=>x.id===id),rows=await api('/admin/content/'+id+'/history');editing={module:item.module,item};modal('内容历史 · '+item.title,rows.length?`<div class="history-list">${rows.map(x=>`<div class="history-item"><div><b>第${x.version}版 · ${esc(x.action)}</b><small>${time(x.created_at)} · ${esc(x.actor_name||'原始资料')}</small><small>${esc(x.data.title||x.data.name||x.data.question||'')}</small></div><div class="actions">${button('查看内容','history-detail',String(x.id))}${canPublish()?button('恢复成草稿','history-restore',String(x.id)):''}</div></div>`).join('')}</div>`:empty('还没有历史版本','第一次修改后会在这里保留旧内容。'));editing.history=rows;}
async function records(){const q=new URLSearchParams({kind:state.recordKind,status:state.recordStatus,q:state.recordSearch,page:state.recordPage});const d=await api('/admin/records?'+q);return heading('每条咨询，都有下文。','处理商品咨询、售后和出行意向。回复保留在原记录中，访客可用原浏览器查看。',canPublish()?button('导出业务CSV','records-export','','primary'):'')+`<form class="toolbar" data-form="record-filter"><label>业务类型<select name="kind"><option value="">全部类型</option>${Object.entries(kindNames).map(([k,v])=>`<option value="${k}" ${state.recordKind===k?'selected':''}>${v}</option>`).join('')}</select></label><label>处理状态<select name="status"><option value="">全部状态</option>${['pending','processing','resolved'].map(k=>`<option value="${k}" ${state.recordStatus===k?'selected':''}>${statusNames[k]}</option>`).join('')}</select></label><label class="search">搜索称呼、地区、编号或说明<input name="q" type="search" value="${esc(state.recordSearch)}"></label><button type="submit">筛选</button></form><section class="panel">${table(['业务与编号','称呼 / 地区','状态','创建时间','操作'],d.items.map(r=>[`${esc(kindNames[r.kind])}<small>${esc(r.id)}</small>`,`${esc(r.name)}<small>${esc(r.region)}</small>`,pill(r.status),time(r.createdAt),button('详情与处理','record',r.id)]))}${paginate(d.total,d.page,d.limit,'records-page')}</section>`;}
async function recordEditor(id){const [r,assignees,relations]=await Promise.all([api('/admin/records/'+id),api('/admin/assignees'),api('/admin/workflow/options')]);editing={record:r};const pairs=[['记录编号',r.id],['类型与时间',kindNames[r.kind]+' / '+time(r.createdAt)],['称呼与地区',r.name+' / '+r.region],['联系方式',r.contact||'未提供'],['商品与数量',r.productName?r.productName+' × '+r.quantity:'—'],['批次',r.batchId||'—'],['日期与人数',r.date?r.date+' / '+r.people+'人（意向，非预约）':'—'],['说明',r.note||'—']];modal('业务详情 · '+kindNames[r.kind],`<dl class="detail-list">${pairs.map(([k,v])=>`<dt>${k}</dt><dd>${esc(v)}</dd>`).join('')}</dl>${r.attachments?.length?'<div class="attachments">'+r.attachments.map(f=>`<a href="${esc(f.url)}" target="_blank" rel="noopener"><img src="${esc(f.url)}" alt="${esc(f.name)}"></a>`).join('')+'</div>':''}<form data-form="followup"><div class="form-grid"><label>处理状态<select name="status">${['pending','processing','resolved'].map(k=>`<option value="${k}" ${r.status===k?'selected':''}>${statusNames[k]}</option>`).join('')}</select></label><label>经办人<select name="assignedTo"><option value="">暂未分配</option>${assignees.map(x=>`<option value="${x.id}" ${r.assignedTo===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><label class="full">关联订单（人工核对原单后选择）<select name="orderId"><option value="">暂未关联</option>${(relations.orders||[]).map(o=>`<option value="${esc(o.id)}" ${r.linkedOrderId===o.id?'selected':''}>${esc(o.title)} · ${esc(o.id)}</option>`).join('')}</select><small>关联用于售后和回访追溯，不修改原始反馈和成交金额。</small></label><label class="full">回复与处理说明<textarea name="reply" maxlength="2000" rows="4">${esc(r.reply)}</textarea><small>访客可查看此回复。完成处理至少填写5个字，不自动构成赔付或预约确认。</small></label></div><p class="form-error" role="alert" hidden></p><div class="dialog-actions">${canPublish()?'<button type="submit" class="primary">保存处理</button>':''}${button('关闭','close')}</div></form>${canPublish()?'<div class="workflow-links">'+button('建立 / 打开客户卡','record-customer',r.id)+'</div>':''}<h3 style="margin-top:24px">跟进历史</h3><div class="history-list">${r.notes.map(n=>`<div class="history-item"><div><b>${esc(n.actor_name||'成员')} · ${esc(statusNames[n.status])}</b><small>${time(n.created_at)}</small><p>${esc(n.reply)}</p></div></div>`).join('')||'<p class="muted">尚未跟进</p>'}</div>`);}
async function drafts(){const [rows,pubs]=await Promise.all([api('/admin/drafts'),api('/admin/publications')]);state.drafts=rows;state.pubs=pubs;return heading('写好，再核对，再发布。','内容编辑可保存并提交；运营或管理员完成7项复核后发布。发布内容显示在前台内容工作室。',canEdit()?button('＋ 新建草稿','draft-new','','primary'):'')+`<section class="panel"><h2>内容草稿</h2>${table(['标题与来源','状态','版本','最近修改','操作'],rows.map(d=>[`${esc(d.title)}<small>${esc(d.sourceRefs.join('；'))}</small>`,pill(d.status),'第'+d.revision+'版',time(d.updatedAt),button('编辑与复核','draft-edit',d.id)]))}</section><section class="panel" style="margin-top:22px"><h2>发布记录</h2>${table(['标题','草稿版本','发布状态','发布时间','操作'],pubs.map(p=>[esc(p.title),'第'+p.revision+'版',p.active?pill('published'):pill('archived'),time(p.createdAt),button('查看','publication-view',p.id)+(p.active&&canPublish()?button('撤回','publication-withdraw',p.id,'small danger'):'')]))}</section>`;}
const checks=['产地与实际发货地','规格与重量分档','批次库存与可售数量','商品价格与计价单位','收货区域与配送费用','采摘安排与发货窗口','售后规则与对外话术'];
function draftEditor(d=null){editing={draft:d};modal(d?'编辑与复核 · '+d.title:'新建内容草稿',`<form data-form="draft"><label>标题<input name="title" value="${esc(d?.title)}" maxlength="120" required></label><label>正文<textarea name="body" rows="8" minlength="10" maxlength="12000" required>${esc(d?.body)}</textarea></label><label>来源依据（每行一条）<textarea name="sourceRefs" rows="2">${esc(d?.sourceRefs.join('\n'))}</textarea><small>至少填写一条。产地、库存、运费、时效和售后应有当批依据。</small></label><p class="form-error" role="alert" hidden></p><div class="actions">${canEdit()?'<button type="submit" class="primary">保存草稿</button>':''}${d&&canEdit()?button('提交复核','draft-submit',d.id):''}${d?button('查看旧版本','draft-history',d.id):''}</div></form>${d?`<hr style="border:0;border-top:1px solid var(--line);margin:24px 0"><div class="panel-top"><h3>事实复核 · ${d.checks.filter(Boolean).length} / 7</h3>${pill(d.status)}</div><p class="muted">请先保存所有修改并提交。勾选代表当前审核人已核对相应依据；修改正文后全部重审。</p>${checks.map((c,i)=>`<label class="check-row"><input type="checkbox" data-draft-check="${i}" ${d.checks[i]?'checked':''} ${!canPublish()||d.status!=='submitted'?'disabled':''}>${c}</label>`).join('')}<div class="dialog-actions">${canPublish()?button('发布到网站','draft-publish',d.id,'primary'):''}${button('关闭','close')}</div>`:''}`);}
async function media(){const rows=await api(state.mediaTab==='uploaded'?'/admin/media':state.mediaTab==='sources'?'/admin/source-media':'/admin/assets');state.assets=rows;return heading('给内容选一张合适的图。','项目素材与后台上传分开管理。售后照片属于私有附件，不会进入公开素材库。')+(canEdit()?`<form class="upload-box" data-form="upload"><label>图片（JPG / PNG / WebP，≤5MB）<input type="file" name="image" accept="image/jpeg,image/png,image/webp" required></label><label>画面说明<input name="alt" maxlength="300" placeholder="用于辅助阅读"></label><label>来源 / 使用授权<input name="sourceRef" maxlength="300"></label><button type="submit" class="primary">上传图片</button><p class="form-error full-width" role="alert" hidden></p></form>`:'')+`<div class="subtabs">${button('后台上传','media-tab','uploaded',state.mediaTab==='uploaded'?'active':'')}${button('项目现有素材','media-tab','project',state.mediaTab==='project'?'active':'')}${button('导入资料素材（仅后台）','media-tab','sources',state.mediaTab==='sources'?'active':'')}</div><label class="toolbar search"><input id="asset-search" type="search" placeholder="搜索素材文件名"></label><div id="asset-list"></div>`;}
function assetList(){const q=$('#asset-search')?.value||'',rows=state.assets.filter(x=>x.name.toLowerCase().includes(q.toLowerCase())),limit=20,page=state.page;$('#asset-list').innerHTML=rows.length?`<div class="asset-grid">${rows.slice((page-1)*limit,page*limit).map(x=>`<article class="asset-card"><img src="/${esc(x.url).replace(/^\//,'')}" alt="${esc(x.alt||x.name)}" loading="lazy"><b>${esc(x.name)}</b>${button('复制素材路径','copy',x.url)}${button('查看原图','asset-view',x.url)}</article>`).join('')}</div>${paginate(rows.length,page,limit,'asset-page')}`:empty('素材库等待第一张图','上传后的图片会持久保存在数据库，供网站各模块选用。');}
async function imagePicker(name){const [uploadRows,assets]=await Promise.all([api('/admin/media'),api('/admin/assets')]);let picker=$('#image-picker');if(!picker){picker=document.createElement('dialog');picker.id='image-picker';document.body.append(picker);}const rows=[...uploadRows,...assets];picker.innerHTML=`<div class="dialog-header"><h2>选择配图</h2>${button('×','picker-close')}</div><div style="padding:22px"><p class="muted">先在“素材库”上传新图，或选择项目现有素材。</p><input id="picker-search" type="search" placeholder="搜索文件名"><div id="picker-grid" class="asset-grid" style="margin-top:18px"></div><p id="picker-count" class="muted"></p></div>`;const render=()=>{const q=$('#picker-search').value.toLowerCase(),filtered=rows.filter(x=>x.name.toLowerCase().includes(q));$('#picker-grid').innerHTML=filtered.slice(0,40).map(x=>`<button class="asset-card" type="button" data-image-url="${esc(x.url)}"><img src="/${esc(x.url).replace(/^\//,'')}" loading="lazy" alt=""><b>${esc(x.name)}</b></button>`).join('');$('#picker-count').textContent=`显示 ${Math.min(40,filtered.length)} / ${filtered.length} 张，可输入关键词继续筛选。`;};$('#picker-search').addEventListener('input',render);picker.onclick=e=>{const b=e.target.closest('[data-image-url]');if(b){$('[data-form="content"]').elements[name].value=b.dataset.imageUrl;picker.close();}};render();picker.showModal();}
async function users(){const rows=await api('/admin/users');state.users=rows;if(state.user.singleAccount)return heading('唯一管理员账号','当前仅允许此账号登录，其他账号已停用。',button('修改密码','password','','primary'))+`<section class="panel">${table(['姓名','账号','角色'],rows.filter(u=>u.active).map(u=>[esc(u.name),esc(u.email),'唯一管理员']))}</section>`;return heading('把工作交给合适的人。','管理员管理账号与设置；运营负责发布、复核与业务；编辑维护内容；只读成员查看数据。',button('＋ 添加成员','user-new','','primary'))+`<section class="panel">${table(['姓名 / 账号','角色','状态','创建时间','操作'],rows.map(u=>[`${esc(u.name)}<small>${esc(u.email)}</small>`,esc(roleNames[u.role]),u.active?pill('active'):pill('inactive'),time(u.createdAt),button('编辑权限','user-edit',u.id)+button('重置密码','user-password',u.id)+button('撤销登录','user-revoke',u.id)]))}</section>`;}
function userEditor(u=null){editing={user:u};modal(u?'编辑成员':'添加成员',`<form data-form="user"><label>姓名<input name="name" value="${esc(u?.name)}" maxlength="60" required></label><label>邮箱账号<input name="email" type="email" value="${esc(u?.email)}" ${u?'readonly':''} required></label><label>角色<select name="role">${Object.entries(roleNames).map(([k,v])=>`<option value="${k}" ${u?.role===k?'selected':''}>${v}</option>`).join('')}</select></label>${u?`<label class="check-row"><input name="active" type="checkbox" ${u.active?'checked':''}>账号可登录</label>`:'<label>临时密码<input name="password" type="password" minlength="12" maxlength="128" autocomplete="new-password" required><small>至少12位，同时包含字母和数字；成员首次登录须修改。</small></label>'}<p class="form-error" role="alert" hidden></p><div class="dialog-actions"><button class="primary" type="submit">保存成员</button>${button('关闭','close')}</div></form>`);}
async function audit(){const d=await api('/admin/audit?page='+state.auditPage);state.logs=d.items;return heading('每次修改，都留有依据。','记录操作人、时间、动作和对象，不保存密码、Cookie与请求正文。')+`<section class="panel">${table(['时间','操作人','动作','对象','操作'],d.items.map(x=>[time(x.created_at),esc(x.actor_name),`${esc(actionLabel(x.action))}<small>${esc(x.action)}</small>`,`<small>${esc(x.entity)}</small>`,button('详情','audit-detail',String(x.id))]))}${paginate(d.total,d.page,d.limit,'audit-page')}</section>`;}
async function system(){const d=await api('/admin/system');return heading('让后台持续、可靠地运行。','本地使用持久化PostgreSQL引擎；上线连接Neon。部署文件只创建Render网页服务。')+`<div class="two-columns"><section class="panel"><h2>运行状态</h2><div class="settings-values">${[['系统版本',d.version],['数据库',d.database==='pglite'?'本地 PostgreSQL / PGlite':'远端 PostgreSQL / Neon'],['运行环境',d.production?'生产':'本地开发'],['Node.js',d.node],['已运行',Math.round(d.uptime/60)+'分钟'],['数据库结构',d.schema],['公开与私有图片',number(Math.round(d.mediaBytes/1024))+'KB'],['内容条数',number(d.counts.content_items)]].map(([k,v])=>`<div><small>${esc(k)}</small><b>${esc(v)}</b></div>`).join('')}</div><p class="wide-note">业务 ${number(d.counts.business_records)} 条 · 访问事件 ${number(d.counts.analytics_events)} 条 · 成员 ${number(d.counts.users)} 位</p></section><section class="panel"><h2>备份与数据保留</h2><p class="muted">${esc(d.backupNote)}</p><div class="actions">${button('下载完整业务备份','backup','','primary')}${button('清理过期统计日志','purge')}</div><p class="wide-note">访问明细保留 ${d.settings.analyticsRetentionDays} 天，HTTP请求保留 ${d.settings.requestRetentionDays} 天。系统每小时清理过期明细，不清空业务或内容。</p><a href="#cms/settings">调整数据保留与统计设置 ↗</a><hr style="margin:24px 0;border:0;border-top:1px solid var(--line)"><h3>从备份恢复</h3><p class="muted">会覆盖现有业务、内容、图片和统计；账号及密码保留，全部会话失效。恢复前会先下载当前数据的备份。</p><form data-form="restore"><label>选择本系统备份<input name="backup" type="file" accept=".gz" required></label><label>输入“恢复并覆盖当前业务数据”<input name="confirmation" autocomplete="off" required></label><p class="form-error" role="alert" hidden></p><button type="submit" class="danger">校验并恢复备份</button></form></section></div>`;}
function actionLabel(action){const names={'content.create':'新增网站内容','content.save':'保存内容草稿','content.publish':'发布网站内容','content.unpublish':'撤下网站内容','content.archive':'归档网站内容','content.restore':'恢复历史为草稿','record.create':'收到访客提交','record.followup':'保存业务跟进','draft.save':'保存运营草稿','draft.submit':'提交事实复核','draft.review':'核验事实项目','draft.publish':'发布运营内容','publication.withdraw':'撤回发布','workflow.create':'新增经营记录','workflow.save':'更新经营记录','workflow.export':'导出经营记录','analytics.export':'导出访问记录','system.restore':'恢复业务备份','system.retention_purge':'清理到期日志','user.create':'创建成员','user.update':'修改成员','auth.login':'成员登录','auth.logout':'退出登录','media.upload':'上传公开素材'};return names[action]||action;}
function guide(){modal('后台操作指南',`<div class="guide"><p>第一次使用先打开“项目与流程”，它把项目书、各模块和下一步工作逐项对应。经营数据在“订单与履约、客户与回访、建议与执行、青年协作与验收”管理；内容发布与业务成交分别记录。</p><h3>1. 修改页面和商品</h3><p>左侧选择模块 → 编辑条目 → 保存草稿 → 检查 → 发布到前台。已发布内容在你再次点击发布前保持原版本。编号用于关联内容，已有编号保持固定。</p><h3>2. 更新问卷</h3><p>在“调查分组与指标”维护样本量与重点指标，在“问卷完整选项”逐项录入题号、选项、人数与有效分母。系统自动计算比例。多选题不要求合计100%。产业端转述与消费者直答分别引用。</p><h3>3. 上传配图</h3><p>先到“素材库”上传图片，填写画面说明和来源，再回各模块点“选图”。售后图片只在业务详情中查看。</p><h3>4. 处理咨询和售后</h3><p>打开“咨询与售后”，筛选待处理记录，分配经办人，填写回复并保存状态。访客在原浏览器可看到自己的记录与回复。系统不自动发送短信或社交消息。</p><h3>5. 运营内容审核</h3><p>新建草稿并注明来源 → 保存 → 提交复核 → 运营核验七项事实 → 发布到网站内容工作室。修改正文后重新审核。这里的发布不代替社交平台官方发布接口。</p><h3>6. 查看访问数据</h3><p>选择日期查看浏览、匿名访客、停留、来源、设备、按钮及意向转化。数据从接入后开始，不补造旧数据。浏览量不等于人数；咨询不等于订单。</p><h3>7. 备份和账号</h3><p>定期下载完整业务备份。备份含访客主动提交的信息和私有附件，请妥善保存。当前站点仅开放一个管理员登录；实际协作者在“协作人员档案”维护，无登录权限，可关联任务执行人，由管理员核对验收。忘记管理员密码时按部署说明使用服务端重置命令。</p></div>`);}
function passwordForm(){const min=state.user?.passwordMinLength||12;modal('修改密码',`<p class="notice-box">${state.user.mustChangePassword?'首次登录请先更换临时密码。':'修改后所有设备上的当前账号登录都会失效。'}</p><form data-form="password"><label>当前密码<input name="currentPassword" type="password" autocomplete="current-password" required></label><label>新密码<input name="password" type="password" minlength="${min}" maxlength="128" autocomplete="new-password" required><small>至少${min}位。</small></label><label>再次输入新密码<input name="confirm" type="password" minlength="${min}" autocomplete="new-password" required></label><p class="form-error" role="alert" hidden></p><button type="submit" class="primary">更换密码并重新登录</button></form>`);}
async function load(){window.PeachAIAdmin?.dispose();window.PeachMaterials?.dispose();if(!state.user||state.user.mustChangePassword)return;const ticket=++generation;state.route=location.hash.slice(1)||'overview';nav();$('#sidebar').classList.remove('open');const title=state.route.startsWith('cms/')?state.modules[state.route.split('/')[1]]?.label:({overview:'工作总览',materials:'资料导入与归档','ai-copy':'商品描述生成','ai-dashboard':'智能数据看板',analytics:'访问分析',records:'咨询与售后',drafts:'内容审核',media:'素材库',users:'成员与权限',audit:'操作记录',system:'备份与运行'}[state.route]||({project:'项目与流程','work/summary':'经营看板','work/orders':'订单与履约','work/customers':'客户与回访','work/signals':'市场与问题','work/decisions':'建议与执行','work/experiments':'小范围验证','work/tasks':'协作与验收','work/collaborators':'协作人员档案'}[state.route])||'工作台');$('#breadcrumb').textContent=title;delete $('#main-content').dataset.route;$('#main-content').innerHTML='<div class="loading"><span class="spinner"></span>正在读取数据…</div>';try{let html;if(state.route==='materials')html=await window.PeachMaterials.page();else if(['ai-copy','ai-dashboard'].includes(state.route))html=await window.PeachAIAdmin.page(state.route);else if(state.route==='work/summary')html=await window.PeachWorkflow.summary();else if(state.route.startsWith('work/'))html=await window.PeachWorkflow.category(state.route.split('/')[1]);else if(state.route.startsWith('cms/'))html=await cms(state.route.split('/')[1]);else{const renderers={overview,analytics,records,drafts,media,users,audit,system,project:window.PeachWorkflow.project};if(!renderers[state.route])throw Error('页面不存在，请从目录重新选择');html=await renderers[state.route]();}if(ticket!==generation)return;$('#main-content').innerHTML=html;if(state.route.startsWith('cms/'))contentList();if(state.route==='media')assetList();if(state.route.startsWith('work/')&&state.route!=='work/summary')window.PeachWorkflow.list();if(state.route==='ai-dashboard')window.PeachAIAdmin.mount();if(state.route==='materials')window.PeachMaterials.mount();document.title='数商桃乡后台 · '+title;$('#main-content').dataset.route=state.route;}catch(e){if(ticket===generation)$('#main-content').innerHTML=heading('暂时无法读取',e.message,button('重新加载','reload','','primary'));}}
async function download(path,fallback){const response=await api(path,{raw:true}),blob=await response.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=response.headers.get('Content-Disposition')?.match(/filename="([^"]+)"/)?.[1]||fallback;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),3000);}
async function action(name,value,el){
 if(await window.PeachAIAdmin?.action(name,value,el))return;
 if(await window.PeachWorkflow?.action(name,value,el))return;
 if(name==='close')return closeModal();if(name==='menu')return $('#sidebar').classList.toggle('open');if(name==='reload')return load();if(name==='guide')return guide();if(name==='password')return passwordForm();
 if(name==='logout'){await api('/auth/logout',{method:'POST',body:{}});showLogin();return;}
 if(name==='content-new')return contentEditor(value,null);if(name==='content-edit'){const item=state.items.find(x=>x.id===value);return contentEditor(item.module,item);}if(name==='content-page'){state.page=Number(value);return contentList();}
 if(name==='add-row'){const field=$(`[data-field="${value}"]`);$('.list-rows',field).insertAdjacentHTML('beforeend',repeatRow(field.dataset.type,field.dataset.type==='metrics'?['',[],null,'']:field.dataset.type==='proofs'?['','','']:['','']));return;}if(name==='remove-row')return el.closest('.list-row').remove();
 if(name==='content-publish'){const item=await saveContent();const saved=await api('/admin/content/'+item.id+'/publish',{method:'POST',body:{version:item.version}});contentEditor(saved.module,saved);notice(saved.module==='source_library'?'已保存档案版本，仅后台可见。':'已发布，前台刷新后可见。');return;}
 if(name==='content-unpublish'||name==='content-archive'){if(!confirm(name==='content-archive'?'归档后会从前台撤下，可从后台重新发布。继续？':'确认撤下当前发布内容？'))return;const item=editing.item;const saved=await api('/admin/content/'+item.id+'/'+(name==='content-archive'?'archive':'unpublish'),{method:'POST',body:{version:item.version}});closeModal();await load();notice('内容已撤下。');return;}
 if(name==='content-preview'&&editing?.module==='source_library')return notice('此资料仅在后台查看，不会公开发布。');if(name==='content-preview'){const saved=canEdit()?await saveContent():editing.item;const routes={pages:saved.slug,products:'consumer',scenarios:'consumer',batches:'trace',trace_steps:'trace',ip_profile:'ip',ip_series:'ip',research_sets:'evidence',survey_rows:'evidence',interviews:'evidence',tours:'rural',faqs:'service',social:'service',slides:'competition',templates:'content',settings:'home',navigation:saved.data.route,home_groups:'home',interface_text:saved.data.scope==='global'?'home':saved.data.scope,feature_controls:'home'};window.open('/?preview='+encodeURIComponent(saved.id)+'#'+routes[saved.module],'_blank','noopener');return;}
 if(name==='content-history')return contentHistory(value);if(name==='history-detail'){const row=editing.history.find(x=>String(x.id)===value);modal('旧版本内容',`<pre class="preview-text">${esc(JSON.stringify(row.data,null,2))}</pre>`);return;}
 if(name==='history-restore'){const saved=await api('/admin/content/'+editing.item.id+'/restore',{method:'POST',body:{version:editing.item.version,historyId:Number(value)}});contentEditor(saved.module,saved);notice('已恢复成草稿，检查后可发布。');return;}
 if(name==='pick-image')return imagePicker(value);if(name==='picker-close')return $('#image-picker')?.close();
 if(name==='record')return recordEditor(value);if(name==='records-page'){state.recordPage=Number(value);return load();}if(name==='records-export')return download('/admin/records-export','业务记录.csv');
 if(name==='analytics-tab'){state.analyticsTab=value;state.eventPage=1;return load();}if(name==='event-page'){state.eventPage=Number(value);return load();}if(name==='analytics-export')return download('/admin/analytics/export?'+rangeQuery(),'访问数据.csv');
 if(name==='draft-new')return draftEditor();if(name==='draft-edit')return draftEditor(state.drafts.find(x=>x.id===value));
 if(name==='draft-submit'){const form=$('[data-form="draft"]'),d=editing.draft;if(form.elements.title.value!==d.title||form.elements.body.value!==d.body||form.elements.sourceRefs.value!==d.sourceRefs.join('\n'))throw Error('请先保存最新修改，再提交复核');const next=await api('/admin/drafts/'+value+'/action',{method:'POST',body:{action:'submit',revision:d.revision}});draftEditor(next);notice('已提交，请由运营完成事实复核。');return;}
 if(name==='draft-publish'){const d=editing.draft;if(['title','body','sourceRefs'].some(k=>$('[data-form="draft"]').elements[k].value!==(k==='sourceRefs'?d.sourceRefs.join('\n'):d[k])))throw Error('请先保存修改并重新复核');await api('/admin/drafts/'+value+'/publish',{method:'POST',body:{revision:d.revision}});closeModal();await load();notice('已发布到网站内容工作室。');return;}
 if(name==='draft-history'){const rows=await api('/admin/drafts/'+value+'/history');modal('草稿历史',rows.length?rows.map(x=>`<div class="panel"><h3>第${x.revision}版 · ${esc(x.title)}</h3><p class="muted">${time(x.created_at)} · ${esc(x.actor_name)}</p><pre class="preview-text">${esc(x.body)}</pre></div>`).join(''):empty('尚无旧版本','修改已保存的内容后，将自动保留前一版本。'));return;}
 if(name==='publication-view'){const p=state.pubs.find(x=>x.id===value);modal(p.title,`<p class="muted">第${p.revision}版 · ${time(p.createdAt)}</p><div class="preview-text">${esc(p.body)}</div><p class="wide-note">来源：${esc(p.sourceRefs.join('；'))}</p>`);return;}
 if(name==='publication-withdraw'){if(!confirm('确认撤回此发布内容？历史记录保留，网站不再显示。'))return;await api('/admin/publications/'+value+'/withdraw',{method:'POST',body:{}});await load();notice('内容已撤回。');return;}
 if(name==='media-tab'){state.mediaTab=value;state.page=1;return load();}if(name==='asset-page'){state.page=Number(value);return assetList();}if(name==='asset-view'){window.open('/'+value.replace(/^\//,''),'_blank','noopener');return;}if(name==='copy'){try{await navigator.clipboard.writeText(value);el.dataset.copyPending='1';notice('路径已复制。');}catch{modal('复制素材路径',`<input readonly value="${esc(value)}">`);}return;}
 if(name==='user-new')return userEditor();if(name==='user-edit')return userEditor(state.users.find(x=>x.id===value));
 if(name==='user-password'){editing={user:state.users.find(x=>x.id===value)};modal('重置成员临时密码',`<p class="notice-box">${esc(editing.user.name)}的新密码会使原有登录失效，成员首次登录须再次修改。</p><form data-form="user-reset"><label>临时密码<input name="password" type="password" minlength="12" maxlength="128" autocomplete="new-password" required></label><p class="form-error" role="alert" hidden></p><button type="submit" class="primary">重置密码</button></form>`);return;}
 if(name==='user-revoke'){if(!confirm('撤销该成员所有设备上的登录？'))return;await api('/admin/users/'+value+'/revoke-sessions',{method:'POST',body:{}});notice('该成员需重新登录。');return;}
 if(name==='audit-page'){state.auditPage=Number(value);return load();}if(name==='audit-detail'){const row=state.logs.find(x=>String(x.id)===value);modal('操作记录',`<pre class="preview-text">${esc(JSON.stringify(row,null,2))}</pre>`);return;}
 if(name==='backup'){await download('/admin/backup','taoxiang-backup.json.gz');notice('备份已下载，请妥善保存。');return;}if(name==='purge'){const r=await api('/admin/purge',{method:'POST',body:{}});await load();notice(`清理过期访问 ${r.events} 条、请求 ${r.requests} 条。`);return;}
 throw Error('未识别此操作');
}
document.addEventListener('click',async e=>{const same=e.target.closest('#navigation a');if(same&&same.hash===location.hash){e.preventDefault();await load();return;}const b=e.target.closest('[data-action]');if(!b||b.disabled)return;e.preventDefault();try{await busy(b,()=>action(b.dataset.action,b.dataset.value,b));}catch(err){showError(err,b.closest('form'));}});
document.addEventListener('submit',async e=>{const form=e.target;if(form.id==='login-form'){e.preventDefault();try{await busy($('[type="submit"]',form),async()=>{const d=Object.fromEntries(new FormData(form)),r=await api('/auth/login',{method:'POST',body:d});if(r.user.demo&&!location.pathname.startsWith('/demo/')){location.href='/demo/admin/';return;}state.user=r.user;state.csrf=r.csrf;form.reset();if(state.user.mustChangePassword){$('#workspace').hidden=false;$('#login-screen').hidden=true;passwordForm();}else await start();});}catch(err){showError(err,form);}return;}
 if(!form.matches('[data-form]'))return;e.preventDefault();const error=$('.form-error',form);if(error)error.hidden=true;try{await busy($('[type="submit"]',form),async()=>{const type=form.dataset.form,d=Object.fromEntries(new FormData(form));
 if(await window.PeachAIAdmin?.submit(form))return;
 if(type==='workflow'){await window.PeachWorkflow.submit(form);return;}
 if(type==='content'){await saveContent();return;}
 if(type==='dates'){state.start=d.start;state.end=d.end;state.eventPage=1;await load();return;}
 if(type==='record-filter'){state.recordKind=d.kind;state.recordStatus=d.status;state.recordSearch=d.q;state.recordPage=1;await load();return;}
 if(type==='followup'){await api('/admin/records/'+editing.record.id,{method:'PATCH',body:{status:d.status,reply:d.reply,assignedTo:d.assignedTo||null,orderId:d.orderId||'',version:editing.record.version}});closeModal();await load();notice('处理记录已保存，访客可查看回复。');return;}
 if(type==='draft'){const old=editing.draft,next=await api('/admin/drafts'+(old?'/'+old.id:''),{method:old?'PATCH':'POST',body:{title:d.title,body:d.body,sourceRefs:d.sourceRefs.split('\n').map(x=>x.trim()).filter(Boolean),...(old?{revision:old.revision}:{})}});draftEditor(next);notice('草稿已保存。改稿后需重新提交和复核。');return;}
 if(type==='upload'){const file=form.elements.image.files[0];if(!file||file.size>5*1024*1024)throw Error('请选择一张不超过5MB的图片');await api('/admin/media',{method:'POST',body:new FormData(form)});state.mediaTab='uploaded';state.page=1;await load();notice('图片已上传并保存在数据库。');return;}
 if(type==='user'){const old=editing.user,body={name:d.name,role:d.role,...(old?{active:d.active==='on'}:{email:d.email,password:d.password})};await api('/admin/users'+(old?'/'+old.id:''),{method:old?'PATCH':'POST',body});closeModal();await load();notice('成员信息已保存。');return;}
 if(type==='user-reset'){await api('/admin/users/'+editing.user.id+'/reset-password',{method:'POST',body:{password:d.password}});closeModal();notice('临时密码已重置。');return;}
 if(type==='password'){if(d.password!==d.confirm)throw Error('两次输入的新密码不一致');await api('/auth/password',{method:'POST',body:{currentPassword:d.currentPassword,password:d.password}});state.user.mustChangePassword=false;closeModal();showLogin();notice('密码已更换，请使用新密码重新登录。');return;}
 if(type==='restore'){if(d.confirmation!=='恢复并覆盖当前业务数据')throw Error('请准确输入恢复确认文字');if(!form.elements.backup.files.length)throw Error('请选择备份文件');await download('/admin/backup','taoxiang-before-restore.json.gz');await api('/admin/restore',{method:'POST',body:new FormData(form)});state.user.mustChangePassword=false;closeModal();showLogin();notice('业务备份已恢复，请重新登录。');return;}
 });}catch(err){showError(err,form);}});
document.addEventListener('input',e=>{if(e.target.id==='cms-search'){state.q=e.target.value;state.page=1;contentList();}if(e.target.id==='asset-search'){state.page=1;assetList();}});
document.addEventListener('change',async e=>{if(e.target.id==='cms-status'){state.page=1;contentList();}if(e.target.matches('[data-draft-check]')){const c=e.target,d=editing.draft;c.disabled=true;try{const next=await api('/admin/drafts/'+d.id+'/action',{method:'POST',body:{action:'review',index:Number(c.dataset.draftCheck),checked:c.checked,revision:d.revision}});const scroll=$('#editor').scrollTop;draftEditor(next);$('#editor').scrollTop=scroll;}catch(err){c.disabled=false;c.checked=!c.checked;showError(err);}}});
$('#editor').addEventListener('cancel',e=>{if(state.user?.mustChangePassword)e.preventDefault();});
$('#editor').addEventListener('close',()=>{if(state.user&&!state.user.mustChangePassword&&$('#workspace').hidden===false)load();});
window.addEventListener('hashchange',()=>{state.page=1;state.q='';state.recordPage=1;load();});
(async()=>{try{const r=await api('/auth/me');state.user=r.user;state.csrf=r.csrf;if(state.user.mustChangePassword){$('#workspace').hidden=false;$('#login-screen').hidden=true;passwordForm();}else await start();}catch(e){if(e.status!==401)showError(e);showLogin();}})();
